local host = require("config.host")

hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })

hl.workspace_rule({ workspace = "special:spotify", on_created_empty = "spotify" })

if host.desktop then
  hl.workspace_rule({ workspace = "special:obs", on_created_empty = "obs" })
  hl.workspace_rule({ workspace = "special:gamestore", on_created_empty = "steam" })
end

